//! The DP operators against the oracle's committed golden fixtures.
//!
//! `oracle/tests/golden/{dataset,queries}.json` are read straight from the repository, so the
//! engine and the Python oracle are checked against the very same bytes. The 20 fixtures cover
//! scalar and grouped `COUNT`/`SUM`, `AVG`, both table policies, filters, and partition
//! suppression. The fixtures are only ever regenerated by the oracle (see its `generate.py`).
//!
//! Integer results must match exactly. Float results may differ by one rounding step
//! (`1e-4`): the noise streams are bit-for-bit, but `ln`/`cos` come from the platform libm, and
//! a one-ulp difference can move a value across a 4-decimal rounding boundary.

use crate::operators::*;
use crate::policy::{ColumnPolicy, Mechanism, TablePolicy};
use privguard_core::{Row, RowSource, Value, VecRowSource};
use std::sync::atomic::Ordering;

// ------------------------------------------------------------------ tiny JSON
#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    /// Value and whether the literal was written as an integer.
    Num(f64, bool),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

impl Parser<'_> {
    fn ws(&mut self) {
        while self.i < self.b.len() && self.b[self.i].is_ascii_whitespace() {
            self.i += 1;
        }
    }

    fn eat(&mut self, s: &str) -> bool {
        self.ws();
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            true
        } else {
            false
        }
    }

    fn string(&mut self) -> String {
        assert!(self.eat("\""));
        let mut out = Vec::new();
        loop {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => return String::from_utf8(out).unwrap(),
                b'\\' => {
                    let e = self.b[self.i];
                    self.i += 1;
                    out.push(match e {
                        b'n' => b'\n',
                        b't' => b'\t',
                        b'r' => b'\r',
                        other => other,
                    });
                }
                c => out.push(c),
            }
        }
    }

    fn value(&mut self) -> Json {
        self.ws();
        if self.eat("null") {
            return Json::Null;
        }
        if self.eat("true") {
            return Json::Bool(true);
        }
        if self.eat("false") {
            return Json::Bool(false);
        }
        match self.b[self.i] {
            b'"' => Json::Str(self.string()),
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                if !self.eat("]") {
                    loop {
                        v.push(self.value());
                        if self.eat("]") {
                            break;
                        }
                        assert!(self.eat(","));
                    }
                }
                Json::Arr(v)
            }
            b'{' => {
                self.i += 1;
                let mut v = Vec::new();
                if !self.eat("}") {
                    loop {
                        self.ws();
                        let k = self.string();
                        assert!(self.eat(":"));
                        v.push((k, self.value()));
                        if self.eat("}") {
                            break;
                        }
                        assert!(self.eat(","));
                    }
                }
                Json::Obj(v)
            }
            _ => {
                let start = self.i;
                while self.i < self.b.len() && !b",]} \n\r\t".contains(&self.b[self.i]) {
                    self.i += 1;
                }
                let text = std::str::from_utf8(&self.b[start..self.i]).unwrap();
                Json::Num(text.parse().unwrap(), !text.contains(['.', 'e', 'E']))
            }
        }
    }
}

fn parse_json(text: &str) -> Json {
    Parser {
        b: text.as_bytes(),
        i: 0,
    }
    .value()
}

impl Json {
    fn get(&self, key: &str) -> &Json {
        match self {
            Json::Obj(kv) => &kv.iter().find(|(k, _)| k == key).expect(key).1,
            other => panic!("not an object: {other:?}"),
        }
    }
    fn arr(&self) -> &[Json] {
        match self {
            Json::Arr(v) => v,
            other => panic!("not an array: {other:?}"),
        }
    }
    fn str(&self) -> &str {
        match self {
            Json::Str(s) => s,
            other => panic!("not a string: {other:?}"),
        }
    }
    fn f64(&self) -> f64 {
        match self {
            Json::Num(n, _) => *n,
            other => panic!("not a number: {other:?}"),
        }
    }
    fn to_value(&self) -> Value {
        match self {
            Json::Null => Value::Null,
            Json::Bool(b) => Value::Bool(*b),
            Json::Num(n, true) => Value::I64(*n as i64),
            Json::Num(n, false) => Value::F64(*n),
            Json::Str(s) => Value::Text(s.clone()),
            other => panic!("not a scalar: {other:?}"),
        }
    }
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

// -------------------------------------------------------------------- fixtures
const GOLDEN: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../oracle/tests/golden");

/// `visits` columns in dataset order; positions are used by the pipeline below.
const COLUMNS: [&str; 8] = [
    "visit_id",
    "patient_id",
    "dept_id",
    "attending_staff_id",
    "admit_ts",
    "discharge_ts",
    "total_charge",
    "admission_type",
];
const VISIT_ID: usize = 0;
const PATIENT_ID: usize = 1;
const TOTAL_CHARGE: usize = 6;

fn col_index(name: &str) -> usize {
    COLUMNS.iter().position(|c| *c == name).expect(name)
}

fn load(file: &str) -> Json {
    let path = format!("{GOLDEN}/{file}");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read golden fixture {path}: {e}"));
    parse_json(&text)
}

fn dataset() -> Vec<Row> {
    load("dataset.json")
        .arr()
        .iter()
        .map(|r| COLUMNS.iter().map(|c| r.get(c).to_value()).collect())
        .collect()
}

/// SQL three-valued filter: NULL never matches, not even `ne`.
fn matches(row: &Row, filter: &Json) -> bool {
    let f = filter.arr();
    let actual = &row[col_index(f[0].str())];
    let want = f[2].to_value();
    let ord = match (actual, &want) {
        (Value::Null, _) => return false,
        (Value::Text(a), Value::Text(b)) => a.cmp(b),
        (a, b) => a
            .as_f64()
            .unwrap()
            .partial_cmp(&b.as_f64().unwrap())
            .unwrap(),
    };
    match f[1].str() {
        "exact" => ord.is_eq(),
        "ne" => ord.is_ne(),
        "gt" => ord.is_gt(),
        "gte" => ord.is_ge(),
        "lt" => ord.is_lt(),
        "lte" => ord.is_le(),
        op => panic!("operator {op}"),
    }
}

struct Outcome {
    rows: Vec<Row>,
    suppressed: u64,
    cal: crate::operators::Calibration,
}

/// Build and run the physical pipeline for one fixture entry.
fn run(q: &Json, data: &[Row]) -> Outcome {
    let agg = match q.get("agg").str() {
        "COUNT" => AggKind::Count,
        "SUM" => AggKind::Sum,
        "AVG" => AggKind::Avg,
        other => panic!("agg {other}"),
    };
    let group = match q.get("group_by") {
        Json::Str(g) => Some(col_index(g)),
        _ => None,
    };
    let value = match q.get("column") {
        Json::Str(c) => Some(col_index(c)),
        _ => None,
    };
    let table = TablePolicy::new(
        q.get("table_policy").get("max_rows_per_unit").f64() as u32,
        q.get("table_policy").get("max_groups_per_unit").f64() as u32,
    )
    .unwrap();
    let column = match q.get("column_policy") {
        Json::Null => None,
        p => Some(
            ColumnPolicy::new(
                Mechanism::parse(p.get("mechanism").str()).unwrap(),
                p.get("lower_clamp").f64(),
                p.get("upper_clamp").f64(),
            )
            .unwrap(),
        ),
    };
    let rho = q.get("rho").f64();
    let delta_part = q.get("delta_partition").f64();
    let seed = hex(q.get("seed_hex").str());

    let filtered: Vec<Row> = data
        .iter()
        .filter(|r| q.get("filters").arr().iter().all(|f| matches(r, f)))
        .cloned()
        .collect();

    let mut src: Box<dyn RowSource> = Box::new(ContributionBound::new(
        VecRowSource::new(filtered),
        PATIENT_ID,
        VISIT_ID,
        group,
        table,
    ));
    if let Some(cp) = &column {
        src = Box::new(Clamp::new(src, TOTAL_CHARGE, cp));
    }
    let mut counter = None;
    if let Some(g) = group {
        let ps = PartitionSelect::new(
            src,
            PartitionConfig {
                unit: PATIENT_ID,
                group: g,
                rho_part: split_budget(rho).0,
                delta_part,
                seed: seed.clone(),
            },
        )
        .unwrap();
        counter = Some(ps.suppressed_counter());
        src = Box::new(ps);
    }
    let cfg = DpAggConfig {
        agg,
        value,
        group,
        table,
        column,
        rho,
        delta: q.get("delta").f64(),
        seed,
    };
    let cal = cfg.calibration().unwrap();
    let mut out = DpAggregate::new(src, cfg).unwrap();
    let rows = out.collect_rows().unwrap();
    Outcome {
        rows,
        suppressed: counter.map_or(0, |c| c.load(Ordering::Relaxed)),
        cal,
    }
}

fn close(a: f64, b: f64, tol: f64) -> bool {
    (a - b).abs() <= tol * (1.0 + b.abs().min(1.0)) || (a - b).abs() <= tol
}

#[test]
fn operators_reproduce_every_oracle_golden_answer() {
    let data = dataset();
    let fixture = load("queries.json");
    let queries = fixture.get("queries").arr();
    assert_eq!(queries.len(), 20);

    for q in queries {
        let id = q.get("id").str();
        let want = q.get("expected");
        let got = run(q, &data);

        // Calibration metadata.
        let cal = &got.cal;
        assert_eq!(cal.mechanism, want.get("mechanism").str(), "{id} mechanism");
        assert!(
            close(cal.sensitivity, want.get("sensitivity").f64(), 1e-12),
            "{id} sensitivity {} vs {}",
            cal.sensitivity,
            want.get("sensitivity").f64()
        );
        assert!(
            close(cal.scale, want.get("scale").f64(), 1e-12),
            "{id} scale"
        );
        assert_eq!(cal.rho_charged, want.get("rho_charged").f64(), "{id} rho");
        assert!(
            close(cal.eps_equivalent, want.get("eps_equivalent").f64(), 1e-9),
            "{id} eps"
        );
        assert_eq!(
            got.suppressed as f64,
            want.get("suppressed_groups").f64(),
            "{id} suppressed groups"
        );

        // Released rows.
        let want_rows = want.get("rows").arr();
        assert_eq!(got.rows.len(), want_rows.len(), "{id} row count");
        for (g, w) in got.rows.iter().zip(want_rows) {
            let (key, value) = match g.as_slice() {
                [v] => (None, v),
                [k, v] => (Some(k), v),
                other => panic!("{id}: unexpected row shape {other:?}"),
            };
            if let Some(k) = key {
                let group_col = q.get("group_by").str();
                assert_eq!(*k, w.get(group_col).to_value(), "{id} group key");
            }
            let wv = w.get("value");
            match (value, wv) {
                (Value::I64(a), Json::Num(b, true)) => assert_eq!(*a, *b as i64, "{id} value"),
                (Value::F64(a), Json::Num(b, _)) => {
                    assert!(close(*a, *b, 1.01e-4), "{id} value {a} vs {b}")
                }
                other => panic!("{id}: value types differ: {other:?}"),
            }
        }
    }
}

#[test]
fn fixtures_exercise_suppression_and_both_bounds() {
    let data = dataset();
    let fixture = load("queries.json");
    let suppressed: u64 = fixture
        .get("queries")
        .arr()
        .iter()
        .map(|q| run(q, &data).suppressed)
        .sum();
    assert!(suppressed > 0, "no fixture suppresses a group");
}
